const failedEmailsView = <Message>(failedEmails: LoadedFailedEmails, h: HtmlBuilder<Message>): Html => {
  const children: Array<Child> = [subSectionTitle(message("settings.failedEmails.title"), h, 2)];
  if (failedEmails._tag === "Failed") {
